pub fn median(_values: &[i64]) -> Option<f64> {
    if _values.is_empty() {
        return None;
    }
    let mut sums = 0.0;
    let mut count = 0;
    for &x in _values.iter() {
        sums += x as f64;
        count += 1;
    }
    if count % 2 == 1 {
        return Some(sums / count);
    }
    return Some((sums / count) * 2.0);
}

